import modlix, json

# Get the app's UI properties to see what's causing the crash
app = modlix.apps.get_ui(app_code='vclone')
print("App keys:", list(app.keys()))
props = app.get('properties', {})
print("Props keys:", list(props.keys()))
fp = props.get('fontPacks', [])
print(f"fontPacks count: {len(fp)}")
if fp:
    print("First fontPack:", json.dumps(fp[0] if fp else {}, indent=2)[:500])
    # Check all font packs for null values
    for i, pack in enumerate(fp):
        families = pack.get('fontFamilies', [])
        for j, fam in enumerate(families):
            for k, v in fam.items():
                if v is None:
                    print(f"NULL found in fontPacks[{i}].fontFamilies[{j}].{k}")
        # Check fontFaces
        faces = pack.get('fontFaces', [])
        for j, face in enumerate(faces):
            for k, v in face.items():
                if v is None:
                    print(f"NULL found in fontPacks[{i}].fontFaces[{j}].{k}")

import modlix, json

cur = modlix.pages.get('home', app_code='vclone')
print("Version:", cur.get('version'))
print("wrapShell:", cur.get('properties', {}).get('wrapShell'))
print("permission:", cur.get('permission'))

# Check component definition structure
cd = cur.get('componentDefinition', {})
print(f"Component count: {len(cd)}")

# Look for any null or problematic values in properties
def find_nulls(obj, path=""):
    if isinstance(obj, dict):
        for k, v in obj.items():
            find_nulls(v, f"{path}.{k}")
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            find_nulls(v, f"{path}[{i}]")
    elif obj is None:
        print(f"NULL at: {path}")

find_nulls(cd)
print("Null scan complete")

