import modlix, json

# Try finding assets from previous extract
result = modlix.get('/api/core/media?appCode=vclone&clientCode=SYSTEM&pageSize=100')
if isinstance(result, dict) and 'content' in result:
    files = result['content']
    print(f"Assets found: {len(files)}")
    for f in files[:40]:
        print(f.get('fileName', ''), '|', f.get('url', '')[:80])
else:
    print(type(result), str(result)[:300])

import modlix, json, copy

# Get full current page
cur = modlix.pages.get('home', app_code='vclone')
cd = copy.deepcopy(cur.get('componentDefinition', {}))

# Fix all non-UUID styleProperty keys
def is_uuid(sk):
    parts = sk.split('-')
    return len(parts) == 5 and all(len(p) in [8, 4, 4, 4, 12] for p in parts)

fixed_count = 0
for comp_key, comp in cd.items():
    sp = comp.get('styleProperties', {})
    bad_keys = [sk for sk in sp.keys() if not is_uuid(sk)]
    if bad_keys:
        for old_key in bad_keys:
            new_key = modlix.uuid()
            sp[new_key] = sp.pop(old_key)
            fixed_count += 1

print(f"Fixed {fixed_count} bad styleProperty keys")

# Build final page definition
new_def = {
    'name': 'home',
    'properties': {
        'wrapShell': False,
    },
    'rootComponent': cur.get('rootComponent'),
    'componentDefinition': cd,
}

result = modlix.pages.replace('home', new_def, app_code='vclone', message='Fix non-UUID styleProperty keys causing TypeError crash')
print(f"Replace result: {result.get('version', result)}")
